def _git_commit_at(path: Path) -> str | None:
    if not path.is_file():
        return None
    try:
        out = subprocess.run(
            ["git", "log", "-1", "--format=%cI", "--", str(path)],
            cwd=ROOT,
            check=False,
            capture_output=True,
            text=True,
        )
    except OSError:
        return None
    text = out.stdout.strip()
    return text or None
